const memo = new Map();
export function flagCode(name) {
  const n = String(name || ''); if (memo.has(n)) return memo.get(n);
  let c = ''; for (const [k, v] of NAMES) if (n.includes(k)) { c = v; break; }
  memo.set(n, c); return c;
}
// 国旗の <img>（代表チームのモードで、国が分かるときだけ）
export function flag(name, cls = '') {
  if (!isNational()) return '';
  const c = flagCode(name); if (!c || !IMG[c]) return '';
  return '<img class="flg ' + cls + '" src="data:image/png;base64,' + IMG[c] + '" alt="" title="' + esc(String(name || '')) + '">';
}
// 「vs 国旗 名前」
export const vsName = (name) => 'vs ' + flag(name) + esc(String(name || ''));
